insert into public.tips (id, unit_id, title_en, body_md, status) values
  ('6f7cea1b-f51c-566f-be92-462456d6f490', 'ae52684a-c28b-5318-92e0-5d1cc5ac5cf1', 'It fell on me', 'Spanish tells accidents as if they happened *to* you: **se me cayó** — *I dropped it* (it fell on me); **se me rompió** — *it broke on me*; **se me olvidó** — *I forgot*. Nobody is to blame, which is the point.', 'draft'),
  ('bc2b8ffb-527b-546f-a547-9c31c7a63d8c', 'ae52684a-c28b-5318-92e0-5d1cc5ac5cf1', 'Se te, se le', 'Change the middle word for the person: **se te cayó** — *you dropped it*; **se le rompió** — *he broke it*.', 'draft'),
  ('23e65acb-db56-56a0-996f-c90f6cdde901', '6dc81d68-66ed-5adc-a6d9-ebdfac00662e', 'Para que', '**Para** + an infinitive when it''s the same person: *estudio para aprender*. **Para que** + the subjunctive when it''s someone else: **te lo mando para que lo leas**.', 'draft'),
  ('6448cf46-bc23-5745-bed1-552fb5525e28', '6dc81d68-66ed-5adc-a6d9-ebdfac00662e', 'Antes de que', '**Antes de que llegue** — *before he gets here* — always takes the subjunctive: it hasn''t happened yet.', 'draft'),
  ('68733a21-83d1-579d-9fce-2d4449ffc000', 'c640ea33-8098-56b9-85a3-15f539f2ece2', 'The past before the past', '**Había** + a participle is the past behind another past: **cuando llegué, ya habían comido** — *when I got there, they''d already eaten*. Buenos Aires uses this one freely.', 'draft'),
  ('bef55cb5-b9c1-55e5-bece-a9cbb5e603a9', 'c640ea33-8098-56b9-85a3-15f539f2ece2', 'Participles', 'Most end in **-ado** or **-ido**: *comido, llegado, salido*. A few don''t: **hecho**, **dicho**, **visto**, **roto**.', 'draft'),
  ('7fe05051-cb0d-51d1-a483-3d0d35b01aa0', '7354baf3-9248-50f2-a9bc-c31acadd98fa', 'Ganamos, perdimos', 'After a match it''s **ganamos**, **perdimos** or **empatamos** — *we* won, even if you were on the sofa. The course leaves the club to you.', 'draft'),
  ('b8f8cc97-9d17-54ae-ac0a-deffbff54047', '7354baf3-9248-50f2-a9bc-c31acadd98fa', 'El hincha', 'A fan is a **hincha**, and a **gol** is shouted, not said.', 'draft'),
  ('17c1c9e2-7e28-5f37-a171-3f6f56f5e112', '98bdf26a-6fb0-57ec-80b0-092e57969285', 'No anda', 'For machines, porteños say **anda** — *it works*: **no anda el wifi**, **¿anda el ascensor?**. *Funciona* is fine, just stiffer.', 'draft'),
  ('c011bb73-3d6a-5f36-8017-766c13874cae', '98bdf26a-6fb0-57ec-80b0-092e57969285', 'Quejarse', '**Me quejé** — *I complained*; **¿de qué te quejás?** — *what are you complaining about?* **Reclamar** is to file a complaint, and something you do a lot with a phone company.', 'draft'),
  ('92568dab-b1e4-5721-9f67-adeec3747987', '5fa3a1dc-bfbe-5b52-a8fb-880e0f0b7173', 'De acuerdo', '**Estoy de acuerdo** — *I agree*. Disagreeing: **para nada** — *not at all*; **depende** — *it depends*; **en parte** — *partly*.', 'draft'),
  ('b617a7a0-808e-54d7-85f8-735996d78f75', '5fa3a1dc-bfbe-5b52-a8fb-880e0f0b7173', 'Softening it', 'A porteño argues hard and softens it: **puede ser, pero…** — *could be, but…*', 'draft'),
  ('bf96bee5-076e-5167-adb6-ac24c4793a4d', '577ff67b-76f7-513b-adca-5871bbb950dc', 'El cajero', 'The ATM is **el cajero** — you go **a sacar plata**. Most porteños split the bill by **transferencia**: **te transfiero** — *I''ll transfer it to you*.', 'draft'),
  ('94d127e4-2339-5415-98ae-ddd06a03e5e1', '20eecfc9-6b84-54ae-aedc-1c389863baf9', 'Me dio miedo', '**Me da miedo** — *it scares me* — works like *gustar*; in a story it''s **me dio miedo**. The reaction afterwards: **¡qué susto!**', 'draft'),
  ('40fdebd8-d0d8-529f-9533-ad6c5e3b4982', 'd7e9f660-01d8-5d0f-9136-9a85a20fc33b', 'Se hace así', '**Se** + a verb says what people do in general: **acá se cena tarde** — *people have dinner late here*; **se saluda con un beso** — *you greet with a kiss*.', 'draft'),
  ('d2d06eea-a98e-54f4-9bd4-27bffe69db00', 'd7e9f660-01d8-5d0f-9136-9a85a20fc33b', 'La previa, la sobremesa', '**La previa** is the drinks before going out; **la sobremesa** is the long chat at the table after eating, which nobody cuts short.', 'draft'),
  ('c7612ab5-0ef0-58d3-b838-a200ee62dd58', '0b94d24b-0ce7-5a34-a580-2ef059801e5e', 'Lo que', '**Lo que** is *what* in the middle of a sentence: **¿viste lo que pasó?**, **no sé lo que quiere**.', 'draft'),
  ('eb718472-c962-5ea6-82e5-8a5d4b4100a9', '0b94d24b-0ce7-5a34-a580-2ef059801e5e', '¡Mirá vos!', '**¡Mirá vos!** — *well, would you look at that* — and **no lo puedo creer** keep the story going. A **chusma** is someone who loves the gossip.', 'draft')
